package app.truemotion.vector;
import java.io.*;
import java.nio.*;
import java.util.*;
import java.util.zip.*;
/** Adobe PSD v1, RGB 8-bit raster channels; unknown editing features are reported. */
public final class PsdFile {
 public static final class Layer{public String name="Layer",blend="norm";public int left,top,width,height,opacity=255,flags,section;public int maskLeft,maskTop,maskWidth,maskHeight,maskDefault=255,maskFlags;public final ArrayList<Channel> channels=new ArrayList<Channel>();public int[] pixels;}
 static final class Channel{int id,length;byte[] data;Channel(int i,int n){id=i;length=n;}}
 public int width,height;public final ArrayList<Layer> layers=new ArrayList<Layer>();public final LinkedHashSet<String> warnings=new LinkedHashSet<String>();public int[] composite;
 static final class Reader{final byte[] data;int p;Reader(byte[] b){data=b;}void require(int n)throws IOException{if(n<0||p>data.length-n)throw new IOException("Truncated PSD");}int u8()throws IOException{require(1);return data[p++]&255;}int u16()throws IOException{return u8()<<8|u8();}int i16()throws IOException{return (short)u16();}int i32()throws IOException{return u8()<<24|u8()<<16|u8()<<8|u8();}String str(int n)throws IOException{require(n);String s=new String(data,p,n,"ISO-8859-1");p+=n;return s;}void skip(int n)throws IOException{require(n);p+=n;}byte[] bytes(int n)throws IOException{require(n);byte[] b=Arrays.copyOfRange(data,p,p+n);p+=n;return b;}int end(int n)throws IOException{require(n);return p+n;}}
 public static PsdFile read(byte[] bytes)throws Exception{Reader r=new Reader(bytes);if(!r.str(4).equals("8BPS")||r.u16()!=1)throw new IOException("Only PSD v1 is supported");r.skip(6);int channels=r.u16();PsdFile result=new PsdFile();result.height=r.i32();result.width=r.i32();int depth=r.u16(),mode=r.u16();if(depth!=8||mode!=3)throw new IOException("PSD needs RGB, 8 bits per channel");if(result.width<1||result.height<1||(long)result.width*result.height>16777216||channels<3||channels>56)throw new IOException("PSD dimensions/channels exceed available limits");r.skip(r.i32());r.skip(r.i32());int layerEnd=r.end(r.i32());
  if(r.p<layerEnd){int infoEnd=r.end(r.i32());if(infoEnd>layerEnd)throw new IOException("Invalid PSD layer section");if(r.p<infoEnd){int count=Math.abs(r.i16());if(count>4096)throw new IOException("Too many PSD layers");for(int i=0;i<count;i++){Layer l=new Layer();l.top=r.i32();l.left=r.i32();int bottom=r.i32(),right=r.i32();l.width=right-l.left;l.height=bottom-l.top;int countChannels=r.u16();if(countChannels>56||l.width<0||l.height<0||(long)l.width*l.height>16777216)throw new IOException("Invalid PSD layer dimensions");for(int c=0;c<countChannels;c++)l.channels.add(new Channel(r.i16(),r.i32()));if(!r.str(4).equals("8BIM"))throw new IOException("Invalid PSD blend record");l.blend=r.str(4);l.opacity=r.u8();r.u8();l.flags=r.u8();r.u8();int extraEnd=r.end(r.i32());if(extraEnd>infoEnd)throw new IOException("Invalid PSD extra data");int maskLength=r.i32(),maskEnd=r.end(maskLength);if(maskLength>=18){l.maskTop=r.i32();l.maskLeft=r.i32();l.maskHeight=r.i32()-l.maskTop;l.maskWidth=r.i32()-l.maskLeft;l.maskDefault=r.u8();l.maskFlags=r.u8();}r.p=maskEnd;r.skip(r.i32());int nameStart=r.p,length=r.u8();l.name=r.str(length);r.skip((4-(r.p-nameStart)%4)%4);
    while(r.p+12<=extraEnd){String signature=r.str(4),key=r.str(4);if(!signature.equals("8BIM")&&!signature.equals("8B64"))break;int blockLength=r.i32(),blockEnd=r.end(blockLength);if(blockEnd>extraEnd)throw new IOException("Invalid PSD metadata block");if(key.equals("luni")){int n=r.i32();if(n<0||n>(blockEnd-r.p)/2)throw new IOException("Invalid PSD layer name");l.name=new String(r.bytes(n*2),"UTF-16BE");}else if(key.equals("lsct")||key.equals("lsdk")){if(blockLength>=4)l.section=r.i32();}else if(key.equals("lfx2")||key.equals("lrFX")||key.equals("SoLd")||key.equals("SoLE")||key.equals("vmsk")||key.equals("TySh"))result.warnings.add("Rasterized/unsupported layer feature: "+key+" ("+l.name+")");r.p=blockEnd;if((blockLength&1)!=0&&r.p<extraEnd)r.skip(1);}r.p=extraEnd;result.layers.add(l);}
   long memory=(long)bytes.length*2;for(Layer l:result.layers){memory+=(long)l.width*l.height*8;for(Channel c:l.channels)if(c.id==-2)memory+=(long)l.maskWidth*l.maskHeight;}long available=Runtime.getRuntime().maxMemory()-Runtime.getRuntime().totalMemory()+Runtime.getRuntime().freeMemory();if(memory>available*.7)throw new IOException("PSD exceeds available memory");
   for(Layer l:result.layers){for(Channel c:l.channels){int end=r.end(c.length);if(end>infoEnd)throw new IOException("Invalid PSD channel size");int w=c.id==-2?l.maskWidth:l.width,h=c.id==-2?l.maskHeight:l.height;if(c.id>=-2&&c.id<=2&&w>0&&h>0&&(long)w*h<=16777216){int compression=r.u16();c.data=plane(r,w,h,compression,end);}r.p=end;}if(l.width>0&&l.height>0){l.pixels=new int[l.width*l.height];byte[] red=null,green=null,blue=null,alpha=null,mask=null;for(Channel c:l.channels){if(c.id==0)red=c.data;else if(c.id==1)green=c.data;else if(c.id==2)blue=c.data;else if(c.id==-1)alpha=c.data;else if(c.id==-2)mask=c.data;}for(int i=0;i<l.pixels.length;i++){int a=alpha==null?255:alpha[i]&255;if(mask!=null&&(l.maskFlags&2)==0){int x=l.left+i%l.width-l.maskLeft,y=l.top+i/l.width-l.maskTop;if((l.maskFlags&1)!=0){x-=l.left;y-=l.top;}int m=x>=0&&y>=0&&x<l.maskWidth&&y<l.maskHeight?mask[y*l.maskWidth+x]&255:l.maskDefault;if((l.maskFlags&4)!=0)m=255-m;a=a*m/255;}l.pixels[i]=a<<24|(red==null?0:red[i]&255)<<16|(green==null?0:green[i]&255)<<8|(blue==null?0:blue[i]&255);}if(!l.blend.equals("norm")&&!l.blend.equals("pass"))result.warnings.add("Blend mode requires checking: "+l.blend+" ("+l.name+")");}for(Channel c:l.channels)c.data=null;}
  }r.p=infoEnd;}r.p=layerEnd;
  if(result.layers.isEmpty()){if((long)result.width*result.height*(channels+8)>Runtime.getRuntime().maxMemory()*.6)throw new IOException("PSD composite exceeds available memory");int compression=r.u16(),size=result.width*result.height;byte[][] rgb=new byte[Math.min(4,channels)][];if(compression==1){int[][] lengths=new int[channels][result.height];for(int c=0;c<channels;c++)for(int y=0;y<result.height;y++)lengths[c][y]=r.u16();for(int c=0;c<channels;c++){byte[] dst=new byte[size];for(int y=0;y<result.height;y++)unpack(r.bytes(lengths[c][y]),dst,y*result.width,result.width);if(c<rgb.length)rgb[c]=dst;}}else if(compression==0){for(int c=0;c<channels;c++){byte[] p=r.bytes(size);if(c<rgb.length)rgb[c]=p;}}else if(compression==2||compression==3){byte[] packed=inflate(r.bytes(r.data.length-r.p),size*channels);for(int c=0;c<rgb.length;c++){rgb[c]=Arrays.copyOfRange(packed,c*size,(c+1)*size);if(compression==3)predict(rgb[c],result.width,result.height);}}else throw new IOException("Unsupported PSD compression");result.composite=new int[size];for(int i=0;i<size;i++)result.composite[i]=(rgb.length>3?rgb[3][i]&255:255)<<24|(rgb[0][i]&255)<<16|(rgb[1][i]&255)<<8|(rgb[2][i]&255);}
  return result;
 }
 static byte[] plane(Reader r,int w,int h,int compression,int end)throws Exception{int size=w*h;byte[] out;if(compression==0)out=r.bytes(size);else if(compression==1){int[] lengths=new int[h];for(int y=0;y<h;y++)lengths[y]=r.u16();out=new byte[size];for(int y=0;y<h;y++)unpack(r.bytes(lengths[y]),out,y*w,w);}else if(compression==2||compression==3){out=inflate(r.bytes(end-r.p),size);if(compression==3)predict(out,w,h);}else throw new IOException("Unsupported PSD channel compression");return out;}
 static byte[] inflate(byte[] input,int length)throws IOException{try(InputStream in=new InflaterInputStream(new ByteArrayInputStream(input))){byte[] out=new byte[length];int p=0,n;while(p<length&&(n=in.read(out,p,length-p))!=-1)p+=n;if(p!=length||in.read()!=-1)throw new IOException("Invalid PSD ZIP channel");return out;}}
 static void predict(byte[] out,int w,int h){for(int y=0;y<h;y++)for(int x=1;x<w;x++)out[y*w+x]=(byte)((out[y*w+x]&255)+(out[y*w+x-1]&255));}
 static void unpack(byte[] packed,byte[] out,int offset,int width)throws IOException{int i=0,p=offset;while(i<packed.length){int n=packed[i++];if(n>=0){n++;if(i+n>packed.length||p+n>offset+width)throw new IOException("Invalid PSD RLE row");System.arraycopy(packed,i,out,p,n);i+=n;p+=n;}else if(n!=-128){n=1-n;if(i>=packed.length||p+n>offset+width)throw new IOException("Invalid PSD RLE repeat");Arrays.fill(out,p,p+n,packed[i++]);p+=n;}}if(p!=offset+width)throw new IOException("Incomplete PSD RLE row");}
}
